@Composable
fun FeedLayout(feed: List<Post>, selected: Post?, onSelect: (Post) -> Unit) {
    val windowClass = currentWindowAdaptiveInfo().windowSizeClass
    val wide = windowClass.isWidthAtLeastBreakpoint(WindowSizeClass.WIDTH_DP_EXPANDED_LOWER_BOUND)
    if (wide) {
        Row(Modifier.fillMaxSize()) {
            PostList(feed, onSelect, Modifier.weight(0.4f))
            VerticalDivider()
            PostDetail(selected, Modifier.weight(0.6f))
        }
    } else {
        PostList(feed, onSelect, Modifier.fillMaxSize())       // detail opens as a separate destination
    }
}

@Composable
fun PlayerScreen(activity: ComponentActivity) {
    val fold by remember { WindowInfoTracker.getOrCreate(activity).windowLayoutInfo(activity) }
        .collectAsStateWithLifecycle(initialValue = null)
    val hinge = fold?.displayFeatures?.filterIsInstance<FoldingFeature>()?.firstOrNull()
    val tabletop = hinge?.state == FoldingFeature.State.HALF_OPENED &&
        hinge.orientation == FoldingFeature.Orientation.HORIZONTAL

    if (tabletop) {
        Column {
            VideoSurface(Modifier.weight(1f))        // top half
            PlayerControls(Modifier.weight(1f))      // bottom half, below the hinge
        }
    } else {
        Box { VideoSurface(Modifier.fillMaxSize()); PlayerControls(Modifier.align(Alignment.BottomCenter)) }
    }
}

