// commonMain
class FeedViewModel(private val repo: NewsRepository) : ViewModel() {
    val state: StateFlow<FeedState> = repo.feed()
        .map { FeedState.Loaded(it) as FeedState }
        .catch { emit(FeedState.Error(it.message ?: "Unknown error")) }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), FeedState.Loading)

    fun refresh() = viewModelScope.launch { repo.refresh() }
}

sealed interface FeedState {
    data object Loading : FeedState
    data class Loaded(val articles: List<Article>) : FeedState
    data class Error(val message: String) : FeedState
}

