// Send the finished workout to the phone app
suspend fun sendWorkout(context: Context, w: Workout) {
    val request = PutDataMapRequest.create("/workouts/${w.id}").apply {
        dataMap.putLong("start", w.start); dataMap.putDouble("km", w.km); dataMap.putInt("avgHr", w.avgHr)
    }.asPutDataRequest().setUrgent()
    Wearable.getDataClient(context).putDataItem(request).await()
}

class PlaybackService : MediaSessionService() {
    private var session: MediaSession? = null

    override fun onCreate() {
        super.onCreate()
        val player = ExoPlayer.Builder(this)
            .setAudioAttributes(AudioAttributes.DEFAULT, /* handleAudioFocus = */ true)
            .setSeekForwardIncrementMs(30_000).setSeekBackIncrementMs(10_000)
            .build()
        session = MediaSession.Builder(this, player).build()     // remote, Assistant and system controls
    }

    override fun onGetSession(controllerInfo: MediaSession.ControllerInfo) = session

    override fun onDestroy() { session?.run { player.release(); release() }; super.onDestroy() }
}

