class ChargingAppService : CarAppService() {
    override fun createHostValidator() =
        if (applicationInfo.flags and ApplicationInfo.FLAG_DEBUGGABLE != 0) HostValidator.ALLOW_ALL_HOSTS_VALIDATOR
        else HostValidator.Builder(this).addAllowedHosts(androidx.car.app.R.array.hosts_allowlist_sample).build()

    override fun onCreateSession() = object : Session() {
        override fun onCreateScreen(intent: Intent): Screen = ChargersScreen(carContext)
    }
}

class ChargerDetailScreen(ctx: CarContext, private val c: Charger) : Screen(ctx) {
    override fun onGetTemplate() = PaneTemplate.Builder(
        Pane.Builder()
            .addRow(Row.Builder().setTitle("${c.free} of ${c.total} free").addText(c.power).build())
            .addAction(Action.Builder().setTitle("Navigate")
                .setOnClickListener { carContext.startCarApp(Intent(CarContext.ACTION_NAVIGATE, Uri.parse("geo:${c.lat},${c.lng}"))) }
                .build())
            .build()
    ).setHeaderAction(Action.BACK).setTitle(c.name).build()
}

