suspend fun showSofa(session: Session) {
    val model = GltfModel.create(session, Paths.get("models", "sofa.glb"))
    val sofa = GltfModelEntity.create(session, model)
    sofa.setPose(Pose(Vector3(0f, -0.6f, -1.5f)))      // 1.5 m in front, a little below eye level
    sofa.setScale(0.8f)
}

